<?php
session_start();require_once __DIR__.'/_auth.php';require_once __DIR__.'/../config/database.php';
function e($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function fotoUrl($foto){$foto=trim((string)$foto);if($foto===''||preg_match('~^(https?:)?//~i',$foto)||strpos(str_replace('\\','/',$foto),'..')!==false)return '';return '../'.ltrim(str_replace('\\','/',$foto),'/');}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(400);exit('ID laporan tidak valid.');}
$stmt=mysqli_prepare($conn,"SELECT l.*,u.nama AS nama_pelapor,u.username FROM laporan l LEFT JOIN users u ON l.user_id=u.id WHERE l.id=?");mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$row=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$row){http_response_code(404);exit('Laporan tidak ditemukan.');}
$src=fotoUrl($row['foto']);
?>
